6	/// Every effect the root runs, in one place.
7	///
8	/// Applied with `.modifier(_:)` rather than through a `View` extension like its
9	/// neighbours: the cluster needs seven collaborators, and a helper taking seven
10	/// arguments is a SwiftLint violation while a memberwise initialiser is not.
11	struct RootLifecycle: ViewModifier {
12	    let session: RobotSession
13	    let viewport: ViewportModel
14	    let floating: FloatingViewportModel
15	    let hfAccount: HFAccount
16	    let remoteRobots: YourReachiesModel
17	    let runningApp: RunningAppModel
18	    let router: ReachyRouter
19	    @Binding var remoteLink: RemoteRobotLink?
20	
21	    @Environment(\.scenePhase) private var scenePhase
22	    @Environment(\.reachyPreviewMode) private var previewMode
23	
24	    func body(content: Content) -> some View {
25	        content
26	            .task {
27	                guard !previewMode else { return }
28	                hfAccount.restore()
29	            }
30	            .onChange(of: hfAccount.state, initial: true) { _, _ in
31	                guard !previewMode else { return }
32	                remoteRobots.accountChanged()
33	            }
34	            .task(id: viewportTarget) {
35	                guard !previewMode else { return }
36	                if let viewportTarget {
37	                    viewport.attach(to: viewportTarget)
38	                } else {
39	                    viewport.detach()
40	                }
41	            }
42	            .onChange(of: viewportIsOnScreen, initial: true) { _, onScreen in
43	                guard !previewMode else { return }
44	                viewport.setActive(onScreen)
45	            }
46	            .onChange(of: keepsRemoteLinkAlive) { _, keepAlive in
47	                guard !keepAlive else { return }
48	                stopRemoteLink()
49	            }
50	            .onOpenURL { url in
51	                // Only a destination this app owns. The OAuth callback shares this
52	                // scheme and belongs to the sign-in session, so `ReachyDeepLink`
53	                // refuses it rather than landing the user on a tab mid-authorisation.
54	                guard let link = ReachyDeepLink(url: url) else { return }
55	                router.follow(link)
56	                if case .runningApp = link {
57	                    runningApp.requestExpansion(for: session)
58	                }
59	            }
60	            .widgetReload(session: session, isPreview: previewMode)
61	    }
62	
63	    /// Both the geometry and the state routes sit behind the backend, so a link
64	    /// alone is not enough to show anything.
65	    ///
66	    /// Over the relay the camera is the peer connection `RemoteRobotLink` already
67	    /// holds — the same one carrying the commands — rather than one this view would
68	    /// dial. Reading `session.address` here is what used to make the Live tab
69	    /// impossible to reach from outside the robot's network.
70	    private var viewportTarget: ViewportModel.Source? {
71	        RootViewportTarget.source(session: session, remoteLink: remoteLink)
72	    }
73	
74	    /// The single lever for battery: nothing streams unless the viewport is the
75	    /// thing the user is actually looking at — and a sleeping robot is never that,
76	    /// however visible the tab is.
77	    ///
78	    /// Two ways of being looked at now, not one. The floating window is the second,
79	    /// and its tab at the edge is what turns it off: `isStreaming` is false the
80	    /// moment the window is docked, and false on a regular width, where there is no
81	    /// window at all.
82	    private var viewportIsOnScreen: Bool {
83	        guard scenePhase == .active, viewportTarget != nil, session.isAwake else { return false }
84	        return router.tab == .live || floating.isStreaming
85	    }
86	
87	    private var keepsRemoteLinkAlive: Bool {
88	        RemoteLinkLifetime.shouldKeepAlive(isRemote: session.isRemote, phase: session.phase)
89	    }
90	
91	    private func stopRemoteLink() {
92	        remoteLink?.stop()
93	        remoteLink = nil
94	    }
95	}
