97	/// Shared by the lifecycle, which decides when to stream, and the Live tab, which
98	/// decides what to draw. Both ask the same question and must not drift.
99	enum RootViewportTarget {
100	    @MainActor
101	    static func source(session: RobotSession, remoteLink: RemoteRobotLink?) -> ViewportModel.Source? {
102	        guard session.isBackendRunning else { return nil }
103	        switch session.link {
104	        case let .lan(address): return .lan(address)
105	        case .remote: return remoteLink.map { .remote($0.camera) }
106	        case .none: return nil
107	        }
108	    }
109	}
