6	/// The sheets the whole interface shares, mounted once above both the gate and the
7	/// shell so that connecting — which throws the tree below it away — does not
8	/// dismiss one mid-flight.
9	///
10	/// **Nothing stateful may be constructed in a sheet's content closure.** SwiftUI
11	/// re-runs that closure on every update of the view the sheet hangs off, which
12	/// here means every `RobotSession.phase` change — and the candidate sweep produces
13	/// one every 10 s while the gate is up. Whatever a model was holding is thrown
14	/// away with it, and a `.task` that filled it does not run a second time. Both
15	/// models below are therefore handed in already built: `remoteRobots` by the root,
16	/// `HFSignInModel` by `HFAccountSection`, which adopts the first one it is given
17	/// into `@State` and ignores every replacement.
18	struct RootSheets: ViewModifier {
19	    let session: RobotSession
20	    let hfAccount: HFAccount
21	    let remoteRobots: YourReachiesModel
22	    let router: ReachyRouter
23	    let connect: (CentralRobot) -> Void
24	
25	    func body(content: Content) -> some View {
26	        @Bindable var router = router
27	        return content
28	            .sheet(isPresented: $router.showsAccount) {
29	                NavigationStack {
30	                    HFSignInScreen(session: session, model: HFSignInModel(account: hfAccount))
31	                        .toolbar {
32	                            ToolbarItem(placement: .cancellationAction) {
33	                                Button(.reachy("Done")) { router.showsAccount = false }
34	                            }
35	                        }
36	                }
37	            }
38	            .sheet(isPresented: $router.showsRemoteRobots) {
39	                NavigationStack {
40	                    YourReachiesScreen(
41	                        model: remoteRobots,
42	                        connect: connect,
43	                        // Pushed inside this sheet rather than sending the user to
44	                        // the robot's Settings tab: that tab does not exist until a
45	                        // robot is connected — exactly the case that brings anyone
46	                        // here.
47	                        signIn: { HFSignInScreen(session: session, model: HFSignInModel(account: hfAccount)) }
48	                    )
49	                }
50	            }
51	            .sheet(isPresented: $router.showsPermissions) {
52	                NavigationStack {
53	                    // Only a LAN session proves the local network was granted; a relay
54	                    // session proves the opposite is possible, which is half the reason
55	                    // this screen is reachable from the gate at all.
56	                    PermissionsScreen(localNetworkProvenByConnection: isConnectedOverLAN)
57	                        .toolbar {
58	                            ToolbarItem(placement: .cancellationAction) {
59	                                Button(.reachy("Done")) { router.showsPermissions = false }
60	                            }
61	                        }
62	                }
63	            }
64	    }
65	
66	    private var isConnectedOverLAN: Bool {
67	        switch session.link {
68	        case .lan: true
69	        // A relay session proves nothing about the local network, and `.none` proves
70	        // less — which is the case this sheet is reachable from the gate for.
71	        case .none, .remote: false
72	        }
73	    }
74	}
